const assert=require('node:assert/strict'),fs=require('node:fs'),vm=require('node:vm');
const source=fs.readFileSync(require('node:path').join(__dirname,'../assets/js/admin-page/admin_walkin.js'),'utf8');let config,rows,scheme;
const venue={value:'10000',selectedIndex:0,options:[{value:'10000',disabled:false,dataset:{id:'1'}}]};const nodes={'event-venue':venue,'summary-breakdown':{},'summary-total-val':{},'summary-due-val':{}};
const document={addEventListener(){},querySelectorAll:()=>rows,querySelector:s=>s.includes('payment-scheme')?{value:scheme}:s==='.admin-booking-container'?{dataset:{eventBundleDiscountPercent:config}}:null};const context={document,window:{},console};vm.createContext(context);vm.runInContext(source+'\nthis.Controller=AdminWalkinController;',context);
function run(percent,roomCost,customCost,paymentScheme){config=String(percent);scheme=String(paymentScheme);rows=[];for(const [system,cost] of [['room_fixture',roomCost],['custom',customCost]])if(cost)rows.push({dataset:{system},querySelector:s=>({value:s.includes('name')?'Synthetic item':String(cost)})});const c=Object.create(context.Controller.prototype);c.state={activeTabId:'tab-event',summary:{},calendars:{event:{totalNights:1}},isDatesLocked:true,activeCalendar:{startDate:new Date()}};c.getEl=id=>nodes[id]||null;c.determineActiveTab=()=>{};c.syncSystemLineItem=()=>{};c.calculateSummary();return c.state.summary;}
let r=run(20,5000,1000,1);assert.equal(r.total,13000,'discount hall+room only, not negotiated fees');assert.match(r.html,/20%/,'review explains configured discount');assert.equal(run(20,5000,0,.5).amountDue,6000,'half payment matches authoritative discounted total');assert.equal(run(20,5000,0,.2).amountDue,2400,'reservation fraction matches discounted total');assert.equal(run(0,5000,0,1).total,15000,'zero discount setting respected');assert.equal(run(30,5000,0,1).total,10500,'non-default configured percent respected');assert.equal(run(100,5000,1000,1).total,1000,'custom fees remain payable under full bundle discount');assert.equal(run(20,0,1000,1).total,11000,'no bundle discount without rooms');console.log('8 actual walk-in review pricing checks: PASS');
